    (forall b, In b Xk -> In b X) -> (forall b, In b Xk -> In b (live MI A')) ->
    (forall q k a, In (q, k) Xk -> q <= a < q + k -> ~ Gf a) -> alloc_ceiling <= fst W ->
    CRep.agree_on (fun a => exists q k, In (q, k) Xk /\ q <= a < q + k) M M'.
