  Lemma state_rep_stores : forall w X A M M' model st c (W : Z -> Prop) lo hi,
    WS w (state_blocks c ++ X) A M model -> state_rep MI A M st c -> stores_in W M M' -> (forall a, W a -> lo <= a < hi) ->
