  Lemma po_tail : forall (w : ww) K (fx : FPState) A8 M8 model8 R8 (p3 p4 p5 p6 p7 p8 : Z),
    let sp := v_sp0 w in let b := v_sp0 w - 672 in let words := v_words w in let n := v_n w in
